}

/* ---------------- Section (Inner Thoughts) ---------------- */
.xt-section{
 margin-bottom:30px;
}

.xt-section-title{
 font-size:11px;
 letter-spacing:4px;
 color:#999;
 margin-bottom:18px;
 text-transform:uppercase;
 font-weight: 500;
}

.xt-section-body{
 background:transparent;
 border:none;
 padding:0;
 line-height:2.1;
 font-size:12px;
 color:#555;
 box-shadow:none;
 display: flex;
 align-items: flex-start;
 gap: 24px;
}

/* 内心独白左侧配图 */
.xt-section-body::before {
 content: "\0020";
 display: block;
 flex-shrink: 0;
 width: 160px;
 height: 160px;
 min-width: 160px;
 min-height: 160px;
 background-image: url('https://img.heliar.top/file/1780751911922_IMG_7471.jpeg');
 background-size: cover;
 background-position: center;
 border-radius: 2px;
 opacity: 0.9;
}

/* ---------------- Grid (Status / BGM) ---------------- */
