 padding:20px;
 box-shadow:none;
 margin-bottom: 16px;
}

.xt-card-title {
 font-size:10px;
 letter-spacing:2px;
 color:#a0a0a0;
 margin-bottom:14px;
 text-transform:uppercase;
 font-weight: 500;
}

.xt-card-body {
 font-size:12px;
 line-height:2.1;
 color:#555;
 display: flex;
 align-items: center;
 gap: 16px;
}

/* ==================================================== */
/* 专门针对 B.G.M 板块的极简专辑图床及文案 */
