.xt-root > .xt-card:nth-of-type(1) .xt-card-body::before,
.xt-root > .xt-card:nth-of-type(2) .xt-card-body::before {
 content: "\0020";
 display: block;
 flex-shrink: 0;
 width: 100px;
 height: 65px;
 min-width: 100px;
 background-image: url('https://img.heliar.top/file/1780751046005_IMG_7472.jpeg');
 background-size: cover;
 background-position: center;
 border-radius: 4px;
 opacity: 0.8;
}

/* ---------------- Quote (Message) ---------------- */
.xt-quote{
 background:transparent;
 border:none;
 padding:0;
 box-shadow:none;
 font-size:12px;
 line-height:2.1;
 color:#555;
 display: flex;
 align-items: center;
 gap: 16px;
}

.xt-quote::before{
 content: "\0020";
 display: block;
 flex-shrink: 0;
 width: 90px;
 height: 60px;
 min-width: 90px;
 background-image: url('https://img.heliar.top/file/1780751046005_IMG_7472.jpeg');
 background-size: cover;
 background-position: center;
 border-radius: 4px;
 opacity: 0.7;
 position: static;
}

.xt-quote::after{
 display: none;
}

/* ---------------- Q&A 气泡板块 ---------------- */
.xt-collapse {
 background: transparent;
 border: none;
 padding: 0;
 box-shadow: none;
 margin-top: 30px;
 margin-bottom: 20px;
}

.xt-collapse-header {
 font-size: 11px;
 letter-spacing: 4px;
 color: #999;
 margin-bottom: 18px;
 text-transform: uppercase;
 font-weight: 500;
}

.xt-collapse-header::after {
 display: none;
}

.xt-collapse-body {
 display: flex;
 flex-direction: column;
 align-items: stretch;
 gap: 16px;
 background: transparent;
 border: none;
 padding: 0;
}

.xt-collapse-body > div {
 padding: 12px 18px;
 font-size: 12px;
 line-height: 1.8;
 max-width: 82%;
 word-wrap: break-word;
}

/* 外人提问气泡 (左侧 - 淡灰色) */
.xt-collapse-body > div:nth-child(odd) {
 align-self: flex-start;
 background: #f4f5f6;
 color: #555;
 border-radius: 14px 14px 14px 2px;
}

/* Char回答气泡 (右侧 - 淡灰蓝色) */
.xt-collapse-body > div:nth-child(even) {
 align-self: flex-end;
 background: #ebf0f5;
 color: #44505c;
 border-radius: 14px 14px 2px 14px;
}

/* ---------------- Footer ---------------- */
.xt-footer{
 margin-top:40px;
 text-align:center;
 font-size:10px;
 letter-spacing:4px;
 color:#b0b0b0;
 text-transform: uppercase;
}

/* ---------------- Scroll ---------------- */
::-webkit-scrollbar{ width:6px; }
::-webkit-scrollbar-thumb{ background:#d8d8d8; border-radius:99px; }

xinshengLayout:
@header charImage charName

@section INNER THOUGHTS
 innerVoice

@divider

@row 2

@card "STATUS"
 @text status
@endcard

@card "B.G.M"
 @text bgm
@endcard

@endrow

@card "OBSESSION"
 @text obsession
@endcard

@card "FRAGMENTS"
 @text fragment
@endcard

@card "MESSAGE"
 @quote message
@endcard

@collapse "Q & A" 1
 @text q1
 @text a1
 @text q2
 @text a2
 @text q3
 @text a3
@endcollapse

@footer PRIVATE JOURNAL

